export async function getTagIndex(): Promise<TagIndex> {
  try {
    const index = await fetchJSON(`${CONFIG.basePath.replace(/\/$/, '')}/content/tags.json`);
    return index || {};
  } catch (error) {
    console.error('Error loading tag index:', error);
    return {};
  }
}

export async function getPostsByTag(tag: string, offset: number = 0, limit: number = 10): Promise<PostMetadata[]> {
  const normalizedTag = tag.toLowerCase().trim();
  const index = await getTagIndex();
  const entry = index[normalizedTag];
  
  if (!entry || !entry.posts.length) return [];
  
  const allPosts = await getAllPostMetadata();
  const taggedSlugs = new Set(entry.posts);
  
  return allPosts
    .filter(p => taggedSlugs.has(p.slug))
    .slice(offset, offset + limit);
}

export async function getTagPageSlugs(tag: string): Promise<string[]> {
  const normalizedTag = tag.toLowerCase().trim();
  const index = await getTagIndex();
  const entry = index[normalizedTag];
  return entry?.pages || [];
}

export async function getRelatedPostSlugs(currentSlug: string, count: number = 3): Promise<string[]> {
  const allPosts = await getAllPostMetadata();
  const currentPost = allPosts.find(p => p.slug === currentSlug);
  
  if (!currentPost || !currentPost.tags || currentPost.tags.length === 0) return [];
  
  const currentTags = new Set(currentPost.tags.map(t => t.toLowerCase().trim()));
  
  const related = allPosts
    .filter(p => p.slug !== currentSlug)
    .map(p => {
      const commonTags = p.tags.filter(t => currentTags.has(t.toLowerCase().trim())).length;
      return { slug: p.slug, commonTags, date: new Date(p.date).getTime() };
    })
    .filter(item => item.commonTags > 0)
    .sort((a, b) => b.commonTags - a.commonTags || b.date - a.date)
    .slice(0, count)
    .map(item => item.slug);
    
  return related;
}

const municipalityFeatureCache = new Map<string, MunicipalityFeature>();

export async function getMunicipalityList(): Promise<MunicipalityInfo[]> {
  try {
    const data = await fetchJSON(`${CONFIG.basePath.replace(/\/$/, '')}/data/nls.fi/municipalities.json`);
    if (Array.isArray(data)) {
      return data;
    }
    if (data && Array.isArray(data.features)) {
      return data.features.map((f: any) => ({
        id: f.id,
        natcode: String(f.properties?.NATCODE || f.properties?.kuntatunnus || '').padStart(3, '0'),
        kuntatunnus: f.properties?.kuntatunnus,
        nameFin: f.properties?.NAMEFIN || '',
        nameSwe: f.properties?.NAMESWE,
        numberOfDetailedPlansInRyhti: f.numberOfDetailedPlansInRyhti ?? f.properties?.numberOfDetailedPlansInRyhti ?? 0,
        numberOfMasterPlansInRyhti: f.numberOfMasterPlansInRyhti ?? f.properties?.numberOfMasterPlansInRyhti ?? 0,
        properties: f.properties
      }));
    }
    return [];
  } catch (error) {
    console.error('Error loading municipality index:', error);
    return [];
  }
}

export const getMunicipalityData = getMunicipalityList;
export const getMunicipalities = getMunicipalityList;

export async function getMunicipalityByCode(code: string): Promise<MunicipalityFeature | null> {
  const rawCode = String(code || '').trim();
  if (!rawCode) return null;
  const padCode = rawCode.padStart(3, '0');

  if (municipalityFeatureCache.has(padCode)) {
    return municipalityFeatureCache.get(padCode) || null;
  }

  try {
    const data = await fetchJSON(`${CONFIG.basePath.replace(/\/$/, '')}/data/nls.fi/municipalities/${padCode}.json`);
    if (data && (data.type === 'Feature' || data.geometry)) {
      municipalityFeatureCache.set(padCode, data);
      municipalityFeatureCache.set(rawCode, data);
      return data;
    }
    return null;
  } catch (error) {
    console.error(`Error loading municipality feature for ${padCode}:`, error);
    return null;
  }
}

